import org.apache.tika.sax.BasicContentHandlerFactory;
import org.apache.tika.parser.ParseContext;
import org.apache.tika.config.OutputLimits;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.Mock;
import org.mockito.Mockito;
import org.mockito.junit.jupiter.MockitoExtension;

import java.io.OutputStream;
import java.io.OutputStreamWriter;
import java.io.UnsupportedEncodingException;
import java.nio.charset.Charset;
import java.util.Locale;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.mockito.Mockito.*;

@ExtendWith(MockitoExtension.class)
public class BasicContentHandlerFactoryTest {

    @Mock
    private ParseContext parseContext;

    @Mock
    private OutputLimits outputLimits;

    private BasicContentHandlerFactory basicContentHandlerFactory;

    @BeforeEach
    public void setUp() {
        basicContentHandlerFactory = new BasicContentHandlerFactory();
    }

    @Test
    public void testNewInstance() {
        when(parseContext.get(OutputLimits.class)).thenReturn(outputLimits);
        when(outputLimits.getWriteLimit()).thenReturn(100);
        when(outputLimits.isThrowOnWriteLimit()).thenReturn(true);

        BasicContentHandlerFactory result = BasicContentHandlerFactory.newInstance(HANDLER_TYPE.MARKDOWN, parseContext);

        assertEquals(HANDLER_TYPE.MARKDOWN, result.getType());
        assertEquals(100, result.getWriteLimit());
        assertEquals(true, result.isThrowOnWriteLimitReached());
        assertEquals(parseContext, result.getParseContext());
    }
}
